/**
 * AutoSPD - Translations
 * Strings live in _locales/<lang>/messages.json (generated by tools/make-locales.py).
 * Chrome picks the language from the browser's UI language.
 */
function t(key, ...substitutions) {
    return chrome.i18n.getMessage(key, substitutions.map(String)) || key;
}

/** Fill data-i18n attributes under root, including inside <template> elements */
function localizePage(root = document) {
    // Lets the browser pick the right CJK glyphs for the language
    if (root === document) document.documentElement.lang = chrome.i18n.getUILanguage();
    const attributes = { 'data-i18n-placeholder': 'placeholder', 'data-i18n-aria-label': 'aria-label', 'data-i18n-title': 'title' };
    for (const element of root.querySelectorAll('[data-i18n]')) {
        element.textContent = t(element.getAttribute('data-i18n'));
    }
    for (const [source, target] of Object.entries(attributes)) {
        for (const element of root.querySelectorAll(`[${source}]`)) {
            element.setAttribute(target, t(element.getAttribute(source)));
        }
    }
    for (const template of root.querySelectorAll('template')) {
        localizePage(template.content);
    }
}
